agent_type.script:
/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
var agent_type= (fd_data._1__look_up_record.record.run_as_user)?"worker":"helper";

return agent_type;

flow_data_definition.script:
/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/

//if worker agent or helper running as user triggering playbook
var isWorker=fd_data._1__look_up_record.record.run_as_user?true:false;
var run_as= '';
if(isWorker)
run_as= JSON.parse(fd_data.subflow_inputs.additional_inputs).supported_by.value || '';

else
run_as= JSON.parse(fd_data.subflow_inputs.additional_inputs).run_as.value || '';

var manual_activity="04808edf1be7001094630f28cc4bcb6e";
var ai_agent_activity="999a05a1ff523210e72effffffffff30";

if(isWorker || run_as=="user_triggering_playbook")
return  manual_activity;

else if(run_as =="active_user" || run_as =="prior_activity_user")
return ai_agent_activity;

